/* Recorded reference outcomes and editable rule drafts, not an arbitrary-input evaluator. */
let diagnosisClass='adult',diagnosisView='Scenarios',diagnosisStory='',diagnosisRuleSearch='';
const diagnosisLabels={adult:'Adults',kid_milk:'Milk-drinking kids',kid_weaning:'Weaning kids',kid_fattening:'Fattening kids'};
function ensureDiagnosisState(){state.healthDiagnosis??={ruleDrafts:{},reviews:[],decisions:{}};if(!diagnosisStory||!diagnosisPack().stories.some(s=>s.id===diagnosisStory))diagnosisStory=diagnosisPack().stories.find(s=>s.recordedResult.hits.length>1)?.id||diagnosisPack().stories[0].id}
function diagnosisPack(){return HEALTH_ENGINE_DATA.packs[diagnosisClass]}function diagnosisScenario(){return diagnosisPack().stories.find(s=>s.id===diagnosisStory)}function diagnosisRules(){return diagnosisPack().register.rules}function diagnosisDraftKey(id){return diagnosisClass+':'+id}function diagnosisRule(id){return diagnosisRules().find(r=>r.id===id)}
function diagnosisSwitchClass(value){diagnosisClass=value;diagnosisStory='';ensureDiagnosisState();renderDiagnosis()}
function renderDiagnosis(){ensureDiagnosisState();const p=diagnosisPack();$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">HEALTH · DIAGNOSIS ENGINE</div><h2>One class pack. Parallel clinical rules.</h2><p>Observe → match all applicable rules → rank Problems → explain gaps → Health Director review.</p></div><button onclick="diagnosisSource()">Source & acceptance ↗</button></div><div class="diagnosis-controls"><label class="field"><span>Class pack</span><select aria-label="Diagnosis class pack" onchange="diagnosisSwitchClass(this.value)">${Object.keys(diagnosisLabels).map(k=>`<option value="${k}" ${diagnosisClass===k?'selected':''}>${diagnosisLabels[k]}</option>`).join('')}</select></label><span class="badge">${esc(p.register.register_version)}</span><span class="muted">${p.register.rules.length} rules · ${p.stories.length} reference scenarios</span></div><div class="diagnosis-tabs">${['Scenarios','Rule register','Review queue'].map(t=>`<button class="${diagnosisView===t?'primary':''}" onclick="diagnosisView='${t}';renderDiagnosis()">${t}</button>`).join('')}</div><div class="notice">Recorded reference scenarios from vgoats/health-sop at ${HEALTH_ENGINE_DATA.sha.slice(0,8)}. These are full oracle outputs captured from the pinned source. Editing a rule does not recalculate them. This mock does not evaluate new clinical observations.</div><div id="diagnosis-body"></div>`;if(diagnosisView==='Scenarios')renderDiagnosisScenario();else if(diagnosisView==='Rule register')renderDiagnosisRules();else renderDiagnosisQueue()}
function diagnosisSource(){modal('Source and acceptance evidence',`<p>vgoats/health-sop · ${HEALTH_ENGINE_DATA.sha}</p><div class="notice">The source reference oracle passed 260 / 260 catalog scenarios: Adults 180, milk-drinking kids 46, weaning kids 21, fattening kids 13. This is evidence for the unmodified source oracle, not a new production engine or edited rule draft.</div><p>Source model: one register per class, parallel clauses, severity separate from confidence, explicit unexplained findings, and Director-confirmed Problems. General SOP workflows and treatment schedules remain separate.</p><a class="diagnosis-source" href="${HEALTH_ENGINE_DATA.source}/engine/ALGORITHM.md" target="_blank" rel="noreferrer">Read algorithm ↗</a><br><a class="diagnosis-source" href="${HEALTH_ENGINE_DATA.source}/engine/ACCEPTANCE.md" target="_blank" rel="noreferrer">Read acceptance contract ↗</a>`)}
function diagnosisTokenList(values,empty='None reported by reference oracle'){return values?.length?values.map(x=>`<span class="diagnosis-token">${esc(x)}</span>`).join(''):`<span class="muted">${empty}</span>`}
function renderDiagnosisScenario(){const s=diagnosisScenario(),r=s.recordedResult,decision=state.healthDiagnosis.decisions[diagnosisClass+':'+s.id];$('#diagnosis-body').innerHTML=`<label class="field"><span>Recorded scenario · observations and results stay paired</span><select aria-label="Recorded diagnosis scenario" onchange="diagnosisStory=this.value;renderDiagnosisScenario()">${diagnosisPack().stories.map(st=>`<option value="${st.id}" ${s.id===st.id?'selected':''}>${st.id} · ${esc(st.title)}</option>`).join('')}</select></label><div class="diagnosis-pipeline"><span>Class & form</span><b>→</b><span>Parallel matches</span><b>→</b><span>Rank & explain</span><b>→</b><span>Director confirmation</span></div><div class="diagnosis-layout"><div><div class="card"><div class="cardheader"><h2>Recorded observations</h2><span class="badge blue">${s.id}</span></div><div class="diagnosis-values">${Object.entries(s.findings).map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(typeof v==='object'?JSON.stringify(v):v)}</b></div>`).join('')}</div><details><summary>Animal and context from source</summary><pre>${esc(JSON.stringify({animal:s.animal,context:s.ctx},null,2))}</pre></details><p class="muted">Only supplied source fields are shown. An absent field is not rewritten as a normal finding. Class selects the applicable form.</p></div><div class="card"><h3>Housing & work list</h3><div class="linkline">Acuity <b>${esc(r.acuity)}</b></div><div class="linkline">Containment <b>${esc(r.containment)}</b></div><div class="linkline">Morning / evening walk <b>${r.morning_walk?'Yes':'No'} / ${r.evening_walk?'Yes':'No'}</b></div><p class="muted">Recorded source output. No animals are moved or tasks scheduled.</p></div></div><div>${!r.valid?`<div class="notice error"><b>Observation rejected</b><br>${esc(r.reject_reason)}</div>`:''}${r.emergencies.length?`<div class="diagnosis-emergency"><h3>Immediate emergency flags</h3>${diagnosisTokenList(r.emergencies)}<p>These source flags do not wait for Director confirmation. This replay sends no instructions.</p></div>`:''}<div class="diagnosis-unexplained"><h3>Unexplained findings</h3>${diagnosisTokenList(r.unexplained)}<p>Keep these visible even when other Problems match.</p></div><h2>Concurrent ranked proposals <span class="muted">${r.hits.length} Problems</span></h2>${r.hits.map((id,index)=>{const match=s.recordedMatches.find(m=>m.id===id),rule=diagnosisRule(id);return `<div class="card diagnosis-proposal"><div class="cardheader"><h2><span class="diagnosis-rank">${index+1}</span>${esc(id)}</h2><span class="badge purple">Confidence: ${esc(r.tiers[id]||match?.tier||'Tier not reported')}</span></div><div class="diagnosis-metrics"><span>Severity <b>${match?.severity??'Not reported'}</b></span><span>SOP <b>${esc(r.sop[id]||rule?.sop_ref||'Not reported')}</b></span></div><span class="label">Matched evidence · recorded matcher</span>${diagnosisTokenList(match?.matched,'Detailed matcher evidence not reported for this pipeline-generated Problem')}<button class="ghost" onclick="diagnosisRuleModal('${id}')">Inspect rule →</button></div>`}).join('')||'<div class="card muted">No Problems proposed by this recorded result. Review actions and unexplained findings below.</div>'}<div class="card"><h3>Actions, rechecks and exclusions</h3>${[['Field actions',r.field_actions],['Rechecks',r.rechecks],['Covered Problems',r.covered],['Director flags',r.hd_flags],['Proposed close',r.propose_close],['Proposed extend',r.propose_extend]].map(([label,values])=>`<div class="diagnosis-output-row"><span class="label">${label}</span>${diagnosisTokenList(values)}</div>`).join('')}<details><summary>Full recorded oracle result</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></div><div class="card"><h2>Health Director decision</h2><p>Confirm the proposal or record an override with a reason. The manager and engine never close a Problem.</p>${decision?`<div class="notice">Local ${esc(decision.action)}<br><b>${decision.action==='override'?'Replacement decision':'Confirmed proposal'}:</b> ${esc(Array.isArray(decision.problems)?decision.problems.join(', '):decision.problems)}<br>${esc(decision.reason||'Proposal confirmed')}<br>${esc(decision.date)}</div>`:''}<div class="actions"><button class="primary" onclick="directorDecision('confirm')" ${!canEdit()||!r.valid?'disabled':''}>Confirm proposal locally</button><button onclick="directorDecision('override')" ${!canEdit()||!r.valid?'disabled':''}>Override with reason</button></div><span class="muted">CEO / CXO is acting as the Health Director in this prototype.</span></div></div></div>`}
function directorDecision(action){const s=diagnosisScenario();modal(action==='override'?'Director override':'Confirm recorded proposal',`<p>${esc(s.id)} · ${esc(s.title)}</p>${action==='override'?`<label class="field"><span>Replacement Problems / decision</span><input id="directorproblems" placeholder="Describe the proposed override"></label><label class="field"><span>Required reason</span><textarea id="directorreason" placeholder="Why does this case need a different decision?"></textarea></label>`:'<p>Record a local confirmation of these recorded proposals. No case is opened and no treatment is authorized by this mock.</p>'}<button class="primary" onclick="saveDirectorDecision('${action}')">Record local ${action}</button>`)}
function saveDirectorDecision(action){if(!canEdit()||!diagnosisScenario()?.recordedResult.valid)return;const reason=action==='override'?$('#directorreason').value.trim():'',problems=action==='override'?$('#directorproblems').value.trim():diagnosisScenario().recordedResult.hits;if(action==='override'&&(!reason||!problems))return toast('Enter the replacement decision and a reason.');state.healthDiagnosis.decisions[diagnosisClass+':'+diagnosisStory]={action,reason,problems,date:new Date().toLocaleString(),sourceSHA:HEALTH_ENGINE_DATA.sha};record('Health Director '+action+' recorded locally for '+diagnosisStory);closeModal();renderDiagnosisScenario()}
function renderDiagnosisRules(){const drafts=state.healthDiagnosis.ruleDrafts;$('#diagnosis-body').innerHTML=`<div class="heading"><div><h2>${diagnosisLabels[diagnosisClass]} rule register</h2><p>Read source rules or prepare a local change for clinical and acceptance review.</p></div><input class="diagnosis-rule-search" aria-label="Search diagnosis rules" placeholder="Search rule or SOP…" value="${esc(diagnosisRuleSearch)}" oninput="diagnosisRuleSearch=this.value;renderDiagnosisRuleRows()"></div><div class="tablewrap card"><table><thead><tr><th>Rule</th><th>Kind</th><th>Severity base</th><th>SOP reference</th><th>State</th><th></th></tr></thead><tbody id="diagnosis-rule-rows"></tbody></table></div>`;renderDiagnosisRuleRows()}
function renderDiagnosisRuleRows(){$('#diagnosis-rule-rows').innerHTML=diagnosisRules().filter(r=>[r.id,r.sop_ref,r.kind].join(' ').toLowerCase().includes(diagnosisRuleSearch.toLowerCase())).map(r=>`<tr><td><b>${esc(r.id)}</b></td><td>${esc(r.kind)}</td><td>${esc(r.severity_base??'—')}</td><td>${esc(r.sop_ref||'—')}</td><td><span class="badge ${canEdit()&&state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(r.id)]?'amber':''}">${canEdit()&&state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(r.id)]?'Local draft':'Source '+diagnosisPack().register.register_version}</span></td><td><button onclick="diagnosisRuleModal('${r.id}')">View / edit →</button></td></tr>`).join('')}
function diagnosisRuleModal(id){let original=diagnosisRule(id);if(!original){modal('Pipeline-generated Problem',`<p>${esc(id)} is present in the recorded output but has no matching register row in this class pack. Inspect the full algorithm for its origin.</p>`);return}let draft=state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(id)],r=canEdit()?(draft?.rule||original):original,dis=!canEdit()?'disabled':'';modal('Rule · '+id,`<div class="notice">${diagnosisLabels[diagnosisClass]} · ${diagnosisPack().register.register_version} · ${draft&&canEdit()?'Local draft changes':'Pinned source rule'}<br>Multiple tier clauses are OR alternatives. Findings within a clause are AND requirements. Confidence tier and severity remain separate.</div><div class="inputrow"><label class="field"><span>Base severity</span><input id="rseverity" type="number" min="1" max="5" value="${r.severity_base??2}" ${dis}></label><label class="field"><span>SOP reference</span><input id="rsop" value="${esc(r.sop_ref||'')}" ${dis}></label></div><label class="field"><span>Applicability · raw source gates</span><textarea id="rgates" rows="5" ${dis}>${esc(JSON.stringify(Object.fromEntries(Object.entries(r).filter(([k])=>k.startsWith('applies_')||['gate_required','gate_excluded'].includes(k))),null,2))}</textarea></label><label class="field"><span>Confidence clauses · raw structured source</span><textarea id="rclauses" rows="9" ${dis}>${esc(JSON.stringify(Object.fromEntries(Object.entries(r).filter(([k])=>['pathognomonic','probable','possible'].includes(k))),null,2))}</textarea></label><details><summary>Full source rule · unchanged reference</summary><pre>${esc(JSON.stringify(original,null,2))}</pre></details><div class="actions"><button class="primary" onclick="saveDiagnosisRule('${id}')" ${dis}>Save review draft</button>${draft?`<button onclick="requestRuleReview('${id}')" ${dis}>Request acceptance review</button><button onclick="discardDiagnosisRule('${id}')" ${dis}>Discard draft</button>`:''}</div><p class="muted">Edited rules are not used by the recorded scenario explorer and cannot be published as clinically accepted through this mock.</p>`,true)}
function validateDiagnosisRule(rule){let errors=[];if(!Number.isInteger(Number(rule.severity_base))||Number(rule.severity_base)<1||Number(rule.severity_base)>5)errors.push('Base severity must be a whole number from 1 to 5.');for(const tier of ['pathognomonic','probable','possible'])if(rule[tier]!==undefined&&(!Array.isArray(rule[tier])||rule[tier].some(c=>!c||!Array.isArray(c.findings))))errors.push(tier+' must contain clauses with findings arrays.');return errors}
function saveDiagnosisRule(id){if(!canEdit())return;let original=diagnosisRule(id),gates,clauses;try{gates=JSON.parse($('#rgates').value);clauses=JSON.parse($('#rclauses').value)}catch{return toast('Gates and clauses must be valid JSON.')}if(!gates||Array.isArray(gates)||typeof gates!=='object'||!clauses||Array.isArray(clauses)||typeof clauses!=='object')return toast('Use JSON objects for gates and clauses.');let allowedGate=k=>k.startsWith('applies_')||['gate_required','gate_excluded'].includes(k);if(Object.keys(gates).some(k=>!allowedGate(k))||Object.keys(clauses).some(k=>!['pathognomonic','probable','possible'].includes(k)))return toast('Use only applicability keys and the three confidence tier keys.');let rule={...structuredClone(original)};for(const key of Object.keys(rule))if(allowedGate(key)||['pathognomonic','probable','possible'].includes(key))delete rule[key];Object.assign(rule,gates,clauses,{severity_base:Number($('#rseverity').value),sop_ref:$('#rsop').value.trim()});let errors=validateDiagnosisRule(rule);if(errors.length)return toast(errors[0]);state.healthDiagnosis.reviews=state.healthDiagnosis.reviews.filter(r=>r.id!==diagnosisDraftKey(id));state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(id)]={rule,status:'Draft — acceptance not run',sourceSHA:HEALTH_ENGINE_DATA.sha,changedAt:new Date().toLocaleString()};record('Saved clinical rule review draft '+id);closeModal();renderDiagnosis();toast('Review draft saved. Recorded scenarios remain unchanged.')}
function discardDiagnosisRule(id){if(!canEdit())return;delete state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(id)];state.healthDiagnosis.reviews=state.healthDiagnosis.reviews.filter(r=>r.id!==diagnosisDraftKey(id));record('Discarded diagnosis rule draft '+id);closeModal();renderDiagnosis()}
function requestRuleReview(id){if(!canEdit())return;let d=state.healthDiagnosis.ruleDrafts[diagnosisDraftKey(id)];if(!d)return;d.status='Awaiting clinical review and full acceptance';state.healthDiagnosis.reviews=state.healthDiagnosis.reviews.filter(r=>r.id!==diagnosisDraftKey(id));state.healthDiagnosis.reviews.unshift({id:diagnosisDraftKey(id),class:diagnosisClass,ruleId:id,sourceSHA:HEALTH_ENGINE_DATA.sha,date:new Date().toLocaleString(),status:d.status});record('Queued local acceptance review '+id);closeModal();diagnosisView='Review queue';renderDiagnosis()}
function renderDiagnosisQueue(){const reviews=state.healthDiagnosis.reviews.filter(r=>r.class===diagnosisClass);$('#diagnosis-body').innerHTML=`<div class="notice">Clinical rule changes require Director review and a full class-catalog acceptance run against the changed engine/register. The 260 passing source stories do not certify edited rules. This local queue sends no external request.</div>${reviews.map((r,index)=>`<div class="card"><div class="cardheader"><h2>${esc(r.ruleId)}</h2><span class="badge amber">${esc(r.status)}</span></div><p>${esc(r.date)} · ${esc(r.sourceSHA.slice(0,8))}</p><button onclick="diagnosisAcceptanceBlock('${r.ruleId}')">Review publication requirements</button></div>`).join('')||'<div class="card empty">No local review requests for this class. Save a rule draft and request acceptance review.</div>'}`}
function diagnosisAcceptanceBlock(id){modal('Publication is not available for this draft',`<h3>${esc(id)} · Required evidence</h3><div class="linkline">Clinical Director review <span class="badge amber">Pending</span></div><div class="linkline">All ${diagnosisPack().stories.length} class scenarios on changed implementation <span class="badge amber">Not run</span></div><div class="linkline">New register version and rollout approval <span class="badge amber">Pending</span></div><p style="margin-top:18px">This mock records the review workflow. It cannot create acceptance evidence or publish a clinical register to GoatOS.</p>`)}
const diagnosisPreviousRender=render;render=function(){diagnosisPreviousRender();if(current==='Health'&&tab!=='Editor'){const t=$('.tabs');if(t)t.insertAdjacentHTML('beforeend',`<button class="${tab==='Diagnosis'?'active':''}" onclick="go('Health','Diagnosis')">Diagnosis</button>`);if(tab==='Diagnosis')renderDiagnosis()}};
let diagnosisClauseDraft={};
function diagnosisVisualClauses(){try{const parsed=JSON.parse($('#rclauses').value);if(!parsed||Array.isArray(parsed)||Object.values(parsed).some(v=>!Array.isArray(v)||v.some(c=>!c||!Array.isArray(c.findings))))throw new Error();diagnosisClauseDraft=parsed}catch{toast('Visual clauses require tier arrays containing findings arrays.');return}let old=$('#visual-clauses');if(!old){$('#rclauses').closest('label').insertAdjacentHTML('beforebegin','<div id="visual-clauses"></div>')}renderVisualClauses()}
function renderVisualClauses(){const dis=!canEdit()?'disabled':'';$('#visual-clauses').innerHTML=`<span class="label">Visual confidence clauses</span><p class="muted">Any clause can match (OR). Every finding inside one clause must match (AND).</p>${['pathognomonic','probable','possible'].map(tier=>`<section class="clinical-tier"><h3>${tier==='pathognomonic'?'Pathognomonic evidence':tier}</h3>${(diagnosisClauseDraft[tier]||[]).map((c,index)=>`<div class="clinical-clause"><div class="clinical-clause-head"><span class="badge blue">${index?'OR':'WHEN'} · ALL findings (AND)</span><button onclick="removeClinicalClause('${tier}',${index})" ${dis}>Remove clause</button></div><div class="clinical-tokens">${c.findings.map((token,ti)=>`<button onclick="removeClinicalToken('${tier}',${index},${ti})" ${dis}>${esc(Array.isArray(token)?token.join(' OR '):token)} ×</button>`).join('')||'<span class="muted">Add a required finding.</span>'}</div><select aria-label="Add required finding to ${tier} clause ${index+1}" onchange="addClinicalToken('${tier}',${index},this.value)" ${dis}><option value="">+ Add required finding</option>${diagnosisPack().register.vocabulary.map(token=>`<option value="${esc(token)}">${esc(token)}</option>`).join('')}</select><label class="checkrow"><input type="checkbox" ${c.residual?'checked':''} onchange="setClinicalResidual('${tier}',${index},this.checked)" ${dis}>Residual clause · only unexplained evidence</label></div>`).join('')}<button onclick="addClinicalClause('${tier}')" ${dis}>+ Add OR clause</button></section>`).join('')}`}
function syncClinicalClauses(){$('#rclauses').value=JSON.stringify(diagnosisClauseDraft,null,2);renderVisualClauses()}
function addClinicalClause(tier){if(!canEdit())return;(diagnosisClauseDraft[tier]??=[]).push({findings:[]});syncClinicalClauses()}
function removeClinicalClause(tier,index){if(!canEdit())return;diagnosisClauseDraft[tier].splice(index,1);if(!diagnosisClauseDraft[tier].length)delete diagnosisClauseDraft[tier];syncClinicalClauses()}
function addClinicalToken(tier,index,value){if(!canEdit()||!value)return;const f=diagnosisClauseDraft[tier][index].findings;if(!f.includes(value))f.push(value);syncClinicalClauses()}
function removeClinicalToken(tier,index,ti){if(!canEdit())return;diagnosisClauseDraft[tier][index].findings.splice(ti,1);syncClinicalClauses()}
function setClinicalResidual(tier,index,value){if(!canEdit())return;diagnosisClauseDraft[tier][index].residual=value;syncClinicalClauses()}
const rawDiagnosisRuleModal=diagnosisRuleModal;diagnosisRuleModal=function(id){rawDiagnosisRuleModal(id);if($('#rclauses')){diagnosisVisualClauses();$('#rclauses').onchange=()=>diagnosisVisualClauses()}};
const basicValidateDiagnosisRule=validateDiagnosisRule;validateDiagnosisRule=function(rule){let errors=basicValidateDiagnosisRule(rule),vocab=new Set(diagnosisPack().register.vocabulary);for(const key of ['applies_species','applies_sex','applies_status','gate_required','gate_excluded'])if(rule[key]!==undefined&&(!Array.isArray(rule[key])||rule[key].some(v=>typeof v!=='string')))errors.push(key+' must be an array of source values.');for(const key of ['gate_required','gate_excluded'])for(const token of Array.isArray(rule[key])?rule[key]:[])if(!vocab.has(token))errors.push('Unknown gate finding: '+token);for(const tier of ['pathognomonic','probable','possible'])if(Array.isArray(rule[tier]))for(const c of rule[tier]){if(!c||!Array.isArray(c.findings)||!c.findings.length)errors.push(tier+': each clause needs at least one finding.');else for(const token of c.findings.flat())if(typeof token!=='string'||!vocab.has(token))errors.push('Unknown finding: '+token)}return [...new Set(errors)]};
